import {BrowserProvider,Contract,Interface,getAddress} from '../vendor/ethers.min.js';
import {launchPlan,swapPlan,redeemPlan,TOKEN_ABI} from './client.mjs';
export class PublicV4Session {
 constructor(onChange=()=>{}){this.onChange=onChange;this.generation=0;this.plan=null;this.raw=null;this.changed=()=>{this.disconnect();this.onChange('The public wallet or chain changed. Prepare a new review.');};}
 async connect(raw=globalThis.ethereum){this.disconnect();if(!raw?.request)throw Error('No injected public wallet is available.');this.raw=raw;raw.on?.('accountsChanged',this.changed);raw.on?.('chainChanged',this.changed);const generation=this.generation;await raw.request({method:'eth_requestAccounts'});this.provider=new BrowserProvider(raw,undefined,{cacheTimeout:-1});this.signer=await this.provider.getSigner();this.address=getAddress(await this.signer.getAddress());this.chainId=(await this.provider.getNetwork()).chainId;if(generation!==this.generation)throw Error('Wallet changed while connecting.');return {address:this.address,chainId:String(this.chainId)};}
 invalidate(){this.generation++;this.plan=null;}
 disconnect(){this.invalidate();this.raw?.removeListener?.('accountsChanged',this.changed);this.raw?.removeListener?.('chainChanged',this.changed);this.provider?.destroy();this.raw=null;this.provider=null;this.signer=null;this.address=null;}
 async assertContext(generation=this.generation){if(!this.raw||!this.address)throw Error('Connect a public wallet first.');const [chain,accounts]=await Promise.all([this.raw.request({method:'eth_chainId'}),this.raw.request({method:'eth_accounts'})]);if(BigInt(chain)!==this.chainId||accounts[0]?.toLowerCase()!==this.address.toLowerCase()||generation!==this.generation)throw Error('Wallet context changed. Prepare a new review.');}
 async prepare(kind,config,input){this.invalidate();const generation=this.generation;await this.assertContext(generation);const builders={launch:launchPlan,swap:swapPlan,redeem:redeemPlan};const plan=await builders[kind](this.provider,config,input,this.address);await this.assertContext(generation);if(BigInt(plan.chainId)!==this.chainId)throw Error('Choose the connected wallet’s chain.');this.plan={...plan,generation};return plan;}
 async next(){const p=this.plan;if(!p)throw Error('Prepare transaction terms first.');await this.assertContext(p.generation);if(Date.now()/1000>=p.deadline)throw Error('Transaction terms expired.');const iface=new Interface(TOKEN_ABI);
  for(const s of p.spend){if(s.tokenAddress.toLowerCase()===p.request.to.toLowerCase())continue;const token=new Contract(s.tokenAddress,TOKEN_ABI,this.provider),allowance=await token.allowance(this.address,p.request.to);if(allowance<s.amount)return {purpose:allowance?'Reset an existing token approval':'Approve the exact transaction budget',request:{to:s.tokenAddress,data:iface.encodeFunctionData('approve',[p.request.to,allowance?0n:s.amount]),value:0n},final:false};}
  return {purpose:p.kind==='launch'?'Create token, pool and liquidity position':p.kind==='redeem'?'Withdraw liquidity and earned fees':'Execute the reviewed public swap',request:p.request,final:true};
 }
 async reviewNext(){const p=this.plan,step=await this.next();await this.provider.call({...step.request,from:this.address});const gas=await this.provider.estimateGas({...step.request,from:this.address});await this.assertContext(p.generation);this.review={...step,generation:p.generation,created:Date.now(),gas};return {...this.review,account:this.address,chainId:String(this.chainId)};}
 async sendReviewed(){const r=this.review;this.review=null;if(!r||Date.now()-r.created>180000)throw Error('Review the next transaction first.');await this.assertContext(r.generation);const next=await this.next();if(next.request.to!==r.request.to||next.request.data!==r.request.data)throw Error('Approval state changed. Review again.');await this.provider.call({...r.request,from:this.address});await this.assertContext(r.generation);const sent=await this.signer.sendTransaction({...r.request,gasLimit:r.gas*120n/100n});const receipt=await sent.wait();if(receipt?.status!==1)throw Error('Public transaction did not succeed.');if(r.final)this.plan=null;return {hash:sent.hash,blockNumber:receipt.blockNumber,final:r.final};}
}
